const solids=[],breakables=[],officers=[],lights=[];function box(x,y,z,w,h,d,m,solid=false){let o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;scene.add(o);if(solid)solids.push(o);return o;}
