const evidence=new THREE.Group();scene.add(evidence);const pouch=new THREE.Mesh(new THREE.BoxGeometry(.36,.07,.27),mat('#c5bb85'));evidence.add(pouch);let cartridge=new THREE.Mesh(new THREE.CylinderGeometry(.035,.035,.19,8),mat('#a88e4b',.8));cartridge.rotation.z=Math.PI/2;cartridge.position.y=.06;evidence.add(cartridge);const marker=new THREE.Mesh(new THREE.OctahedronGeometry(.12),new THREE.MeshBasicMaterial({color:'#d8e7a2'}));scene.add(marker);
