let audio;function sound(freq=140,dur=.15,type='triangle',vol=.12){if(!audio)return;let o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(25,freq*.3),audio.currentTime+dur);g.gain.setValueAtTime(vol,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}
let save;try{save=JSON.parse(localStorage.getItem('own-save'))}catch{}let state={credits:save?.credits||0,levels:save?.levels||[0,0,0,0],arrests:save?.arrests||0,stage:0,quick:false,active:false,collateral:0,culprit:0,firstAction:null};let time=0,shake=0,flash=0,scan=0,jump=0,vy=0,yaw=0,pitch=0,toastTime=0,step=0,frames=0,fps=60;const keys={};
function persist(){if(!state.quick)localStorage.setItem('own-save',JSON.stringify({credits:state.credits,levels:state.levels,arrests:state.arrests}))}function toast(t){$('#toast').textContent=t;toastTime=2}
function newCase(){state.stage=0;state.culprit=Math.floor(Math.random()*3);const spots=[[1.1,1.04,1.7],[4,.12,5],[12,.95,6]];evidence.position.set(...spots[state.arrests%3]);evidence.visible=true;for(let o of officers){o.mesh.position.set(...(o.index===0?[.4,0,-.7]:o.index===1?[-3,0,-4.5]:[12,0,8]));}update();}
function update(){ $('#stats').innerHTML=`▣ ${state.credits} &nbsp; / &nbsp; ${state.arrests} ✓<br><small>Collateral ${state.collateral}</small>`;$('#objective').textContent=['◇ Recover physical proof','▱ Present at table','⇢ Confront marked officer','⚡ Pursue & restrain'][state.stage];toolRings.forEach((r,i)=>r.visible=i<=state.levels[0]);}
function start(quick){if(state.quick&&!quick){try{let old=JSON.parse(localStorage.getItem('own-save'));state.levels=old?.levels||[0,0,0,0];state.credits=old?.credits||0;state.arrests=old?.arrests||0}catch{}}state.quick=quick;state.active=true;if(quick)state.levels=[3,3,3,3];$('#menu').style.display='none';audio??=new AudioContext();audio.resume();renderer.domElement.requestPointerLock();newCase();}
$('#main').onclick=()=>start(false);$('#quick').onclick=()=>start(true);renderer.domElement.onclick=()=>{if(state.active)renderer.domElement.requestPointerLock()};
function quality(q){if(q==='auto')q=navigator.hardwareConcurrency<=4?'low':'medium';renderer.setPixelRatio(q==='low'?1:Math.min(devicePixelRatio,q==='high'?2:1.35));renderer.shadowMap.enabled=q!=='low';lights.forEach((l,i)=>{l.castShadow=q!=='low'&&i===0;l.shadow.mapSize.set(512,512)});}
$('#quality').onchange=e=>quality(e.target.value);quality('auto');
const branches=['◎ Forensics','➚ Pursuit','⊕ Restraint','▥ Facilities'];function upgrades(){let el=$('#upgrades');el.style.display=el.style.display==='block'?'none':'block';el.innerHTML='<h2>Department equipment</h2>';branches.forEach((b,i)=>{let level=state.levels[i],cost=100*Math.pow(2,level);let btn=document.createElement('button');btn.textContent=`${b} ${level}/6 · ${level===6?'MAX':cost+' ▣'}`;btn.onclick=()=>{if(level<6&&state.credits>=cost){state.credits-=cost;state.levels[i]++;sound(580,.3);toast('EQUIPMENT IMPROVED');persist();update();el.style.display='none';upgrades()}};el.append(btn)});document.exitPointerLock();}
function dist(p){return Math.hypot(camera.position.x-p.x,camera.position.z-p.z)}
function act(){if(!state.active)return;state.firstAction??=performance.now();sound(230,.12);shake=.08;
if(state.stage===0&&dist(evidence.position)<2.2){state.stage=1;evidence.visible=false;toast('PROOF SECURED');}
else if(state.stage===1&&dist(table.position)<2.9){state.stage=2;evidence.position.set(0,1.06,1.2);evidence.visible=true;toast('REACTION IDENTIFIED');sound(70,.6,'sawtooth');}
else if(state.stage===2&&dist(officers[state.culprit].mesh.position)<3){state.stage=3;toast('SUSPECT FLEEING');sound(380,.3,'square');}
else if(state.stage===3&&dist(officers[state.culprit].mesh.position)<1.8+state.levels[2]*.4){state.arrests++;let reward=160+state.levels[0]*45+state.levels[3]*35;state.credits+=reward;toast(`+${reward}  RESTRAINED`);sound(650,.4);shake=.2;persist();if(state.quick){state.active=false;$('#menu').style.display='block';$('#menu h2').textContent=`Shift: ${Math.max(0,100-state.collateral*3)} / 100`;document.exitPointerLock()}else newCase();}update();}
function smash(){let target=breakables.filter(b=>b.hp&&dist(b.pos)<2.6).sort((a,b)=>dist(a.pos)-dist(b.pos))[0];if(!target)return;target.hp=0;target.mesh.visible=false;let i=solids.indexOf(target.mesh);if(i>=0)solids.splice(i,1);state.collateral++;shake=.25;sound(target.type==='glass'?1000:90,.3,'sawtooth');for(let j=0;j<24;j++)debris.push({p:target.pos.clone().add(new THREE.Vector3(0,.5,0)),v:new THREE.Vector3((Math.random()-.5)*5,Math.random()*4,(Math.random()-.5)*5),life:3});update();}
addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','Tab'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='KeyE')act();if(e.code==='KeyQ'){scan=2;sound(520,.5,'sine');state.firstAction??=performance.now()}if(e.code==='KeyF')smash();if(e.code==='Tab')upgrades();if(e.code==='Space'&&jump===0){vy=4.5+state.levels[1]*.25;sound(90,.1)}});addEventListener('keyup',e=>keys[e.code]=false);addEventListener('mousemove',e=>{if(document.pointerLockElement){yaw-=e.movementX*.002;pitch=Math.max(-1.4,Math.min(1.4,pitch-e.movementY*.002));}});
function blocked(x,z){if(Math.abs(x)>16.5||Math.abs(z)>16.5)return true;return solids.some(o=>{let p=o.position,s=o.geometry.parameters;return s.height>jump+.5&&Math.abs(x-p.x)<s.width/2+.23&&Math.abs(z-p.z)<s.depth/2+.23});}
let last=performance.now();function tick(now){requestAnimationFrame(tick);let dt=Math.min(.04,(now-last)/1000);last=now;time+=dt;frames++;if(frames%30===0)fps=Math.round(1/dt);if(state.active){let dx=(keys.KeyD?1:0)-(keys.KeyA?1:0),dz=(keys.KeyS?1:0)-(keys.KeyW?1:0);let len=Math.hypot(dx,dz)||1,speed=(keys.ShiftLeft?4.7:2.7)+state.levels[1]*.32;let x=(dx*Math.cos(yaw)+dz*Math.sin(yaw))/len*dt*speed,z=(-dx*Math.sin(yaw)+dz*Math.cos(yaw))/len*dt*speed;if(dx||dz){state.firstAction??=now;if(!blocked(camera.position.x+x,camera.position.z))camera.position.x+=x;if(!blocked(camera.position.x,camera.position.z+z))camera.position.z+=z;step+=dt*speed;if(step>.9){sound(65+Math.random()*25,.06,'triangle',.045);step=0}}vy-=12*dt;jump=Math.max(0,jump+vy*dt);if(jump===0)vy=0;let ground=0;if(state.levels[3]>=2&&camera.position.z>-4.6&&camera.position.z<-3.1&&camera.position.x>=8.8&&camera.position.x<=13.3)ground=Math.min(2.8,(camera.position.x-8.8)*.64);if(state.levels[3]>=2&&camera.position.x>9.5&&camera.position.x<16.5&&camera.position.z<-4.5&&camera.position.z>-7.5)ground=2.8;camera.position.y=1.65+ground+jump+((dx||dz)?Math.sin(time*11)*.035:0);if(state.stage===3){let o=officers[state.culprit],p=o.mesh.position;let target=new THREE.Vector3(12+Math.sin(time*.48)*3,0,Math.cos(time*.48)*9);let v=target.sub(p);let sp=2.1;v.y=0;if(v.length()>.2){v.normalize();p.addScaledVector(v,dt*sp);o.mesh.rotation.y=Math.atan2(v.x,v.z);o.mesh.position.y=Math.abs(Math.sin(time*12))*.08;}}}
shake=Math.max(0,shake-dt*.6);camera.rotation.set(pitch+(Math.random()-.5)*shake,yaw+(Math.random()-.5)*shake,0);scan=Math.max(0,scan-dt);marker.visible=state.active;let target=state.stage===0?evidence.position:state.stage===1?table.position:officers[state.culprit].mesh.position;marker.position.copy(target);marker.position.y+=1.1+Math.sin(time*3)*.08;marker.rotation.y=time;marker.scale.setScalar(scan>0?1.7:1);if(state.stage===1){evidence.position.copy(camera.position);let forward=new THREE.Vector3(.1,-.35,-.7).applyEuler(camera.rotation);evidence.position.add(forward);evidence.visible=true;}
for(let i=debris.length-1;i>=0;i--){let d=debris[i];d.life-=dt;if(d.life<=0){debris.splice(i,1);continue}d.v.y-=9*dt;d.p.addScaledVector(d.v,dt);if(d.p.y<.07){d.p.y=.07;d.v.y*=-.35;d.v.x*=.96;d.v.z*=.96}}for(let i=0;i<240;i++){let d=debris[i];dummy.position.copy(d?d.p:new THREE.Vector3(0,-50,0));dummy.rotation.set(time*i*.1,0,i);dummy.updateMatrix();debrisMesh.setMatrixAt(i,dummy.matrix)}debrisMesh.instanceMatrix.needsUpdate=true;
if(toastTime>0){toastTime-=dt;if(toastTime<=0)$('#toast').textContent=''}let near=dist(target);$('#prompt').textContent=state.active&&near<(state.stage===1?2.9:3)?['E · SECURE PROOF','E · SLIDE INTO LIGHT','E · CONFRONT','E · RESTRAIN'][state.stage]:scan>0?'◇ TRACE LOCATED':'';renderer.render(scene,camera);}
newCase();requestAnimationFrame(tick);addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});

